insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-01$q$,$q$LS-54$q$,array[$q$LS-54$q$]::text[],$q$الأبواب والأقفال والإكسسوارات المعدنية$q$,$q$card$q$,10,$q$الأبواب المعدنية والمقاومة للحريق$q$,$q$Hollow Metal & Fire‑Rated Doors$q$,$q$list$q$,$q$HÖRMANN أو الكحيمي أو الدريس$q$,array[$q$HD$q$,$q$HT$q$,$q$FIRE$q$]::text[],$q$[["سماكة ضلفة الباب", "0.8 – 1.2 مم غالباً", "1.6 مم (Gauge 16) — فئة «Extra Heavy Duty» في ANSI/SDI A250.8"], ["سماكة الحلق (الإطار)", "1.2 – 1.5 مم", "2.0 مم (Gauge 14)"], ["أبواب الحريق", "ملصق غير موثّق أو باب عادي بمظهر مشابه", "باب مُختبَر ومعلّم بملصق جهة اختبار معتمدة للمدة المطلوبة، ومطابق لشهادته بالكامل (الحلق والمفصلات والقفل والمغلاق)"], ["التشطيب", "دهان عادي", "دهان بودرة مخبوز يتحمّل التنظيف المتكرر"], ["حماية أسفل الباب", "لا يوجد", "لوح حماية (Kick Plate) بارتفاع 90 سم من CS Group"]]$q$::jsonb,$q$الضلفة الرقيقة تنبعج من أول اصطدامات الأسرّة والعربات، فينحرف الباب ويختلّ إحكام القفل والمغلاق. وباب الحريق ليس «باباً سميكاً» فقط؛ هو منظومة مختبرة كاملة، وأي تغيير في مكوّن منها يُسقط تصنيفها.$q$,$q$انبعاج وتقشّر خلال أشهر، وأبواب حريق لا تُغلق ذاتياً أو تسرّب الدخان، وملاحظات في زيارات الدفاع المدني والاعتماد (سباهي) تستوجب الاستبدال.$q$,array[$q$شهادة اختبار الحريق وصورة الملصق$q$,$q$كتالوج يوضّح السماكات والحشوة$q$,$q$عينة مقطع من الضلفة$q$,$q$جدول الأبواب والإكسسوارات (Door Schedule)$q$]::text[],'{}'::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-02$q$,$q$LS-54$q$,array[$q$LS-54$q$]::text[],$q$الأبواب والأقفال والإكسسوارات المعدنية$q$,$q$card$q$,20,$q$المفصلات والمغلقات ومقابض الطوارئ$q$,$q$Door Hardware — ANSI/BHMA Grade 1$q$,$q$eq$q$,$q$درجة ANSI/BHMA Grade 1 لكل الإكسسوارات$q$,array[$q$G1$q$,$q$HD$q$,$q$HT$q$]::text[],$q$[["المفصلات (A156.1)", "Grade 3: نحو 350,000 دورة", "Grade 1: 2,500,000 دورة"], ["مغلقات الأبواب (A156.4)", "Grade 3: نحو 500,000 دورة", "Grade 1: 2,000,000 دورة"], ["أقفال الغاطس Mortise (A156.13)", "Grade 3: نحو 800,000 دورة", "Grade 1: 1,000,000 دورة + اختبارات قوة أعلى"], ["الأقفال الأسطوانية (A156.2)", "Grade 3: نحو 200,000 دورة", "Grade 1: 1,000,000 دورة"], ["أجهزة الخروج Panic (A156.3)", "Grade 3: نحو 100,000 دورة", "Grade 1: 500,000 دورة"]]$q$::jsonb,$q$الدورة = فتحة وإغلاقة واحدة. باب ممر يُستخدم 300 مرة يومياً يستهلك أكثر من 100,000 دورة في السنة؛ أي أن إكسسوار الدرجة الثالثة قد ينتهي عمره الافتراضي في سنوات قليلة، بينما صُمّمت الدرجة الأولى للمباني التجارية والمؤسسية الكثيفة.$q$,$q$مغلقات تسرّب الزيت وتصفق الأبواب، ومفصلات تهبط فيحتكّ الباب بالأرض، ومقابض طوارئ تتعطل في أخطر لحظة.$q$,array[$q$شهادة BHMA أو تقرير اختبار يذكر الدرجة صراحةً لكل صنف$q$,$q$كتالوج الموديل المورَّد$q$]::text[],array[1]::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-03$q$,$q$LS-54$q$,array[$q$LS-54$q$]::text[],$q$الأبواب والأقفال والإكسسوارات المعدنية$q$,$q$card$q$,30,$q$الأقفال الإلكترونية SALTO$q$,$q$SALTO XS4 Original Wide · PBE900 Panic$q$,$q$only$q$,$q$SALTO XS4 Original Wide للأقفال، وPBE900 لأبواب الطوارئ — عبر الموزّع المعتمد فقط$q$,array[$q$UNI$q$,$q$HD$q$]::text[],$q$[["طريقة الدخول", "مفتاح ميكانيكي أو قفل إلكتروني منزلي/فندقي", "بطاقة دخول ضمن منظومة صلاحيات مركزية مع Master Key"], ["إدارة الصلاحيات", "نسخ المفاتيح وفقدها، لا يمكن سحب الصلاحية", "تُمنح وتُسحب الصلاحية بالبطاقة فوراً"], ["سجل الدخول", "لا يوجد", "سجل تدقيق داخل القفل (650 – 1,000 حدث)"], ["البطارية", "—", "3 بطاريات AA تكفي نحو 40,000 – 60,000 فتحة"], ["التوريد والبرمجة", "أي مورّد", "الموزّع المعتمد فقط: البرمجة والترخيص والضمان"]]$q$::jsonb,$q$غرف الأدوية والسجلات الطبية وغرف الخوادم والمستودعات تحتاج ضبط وصول موثّقاً. ووجود منظومة واحدة في كل منشآت التجمع يعني بطاقة واحدة للموظف، وبرمجيات واحدة، وفريق صيانة واحد.$q$,$q$قفل خارج المنظومة لا يمكن ربطه ولا إدارته، فيبقى جزيرة منفصلة ويُستبدل عند أول تشغيل. والتوريد من غير الموزّع المعتمد قد يعني عدم القدرة على البرمجة أو فقدان الضمان.$q$,array[$q$خطاب الموزّع المعتمد لـ SALTO$q$,$q$جدول الأقفال لكل باب$q$,$q$تأكيد التوافق مع منظومة التجمع القائمة$q$]::text[],array[2]::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-04$q$,$q$LS-55$q$,array[$q$LS-55$q$]::text[],$q$الأبواب والأقفال والإكسسوارات المعدنية$q$,$q$card$q$,40,$q$الباب الأوتوماتيكي المنزلق$q$,$q$dormakaba (Dorma) EL 301 — Heavy Use$q$,$q$eq$q$,$q$Dorma EL 301 أو ما يعادله بعد الاعتماد$q$,array[$q$HD$q$,$q$HT$q$,$q$247$q$]::text[],$q$[["فئة المحرك", "محرك تجاري خفيف", "محرك مخصص للاستخدام الكثيف المتواصل"], ["عند انقطاع الكهرباء", "قد يتوقف مغلقاً", "آلية Fail‑safe بالفتح، مع بطارية احتياطية لمدة ساعة"], ["السلامة", "حساس حركة بسيط", "حساسات حركة وأمان وفق متطلبات EN 16005 للأبواب الآلية"], ["الخدمة", "لا وكيل محلي", "وكيل معتمد وقطع غيار متوفرة"]]$q$::jsonb,$q$المدخل الرئيسي يمر منه المرضى والزوار والأسرّة على مدار الساعة، وقد يكون مسار إخلاء. الباب يجب أن يفتح بأمان، ولا يغلق على مريض أو كرسي متحرك، ويفتح تلقائياً عند الطوارئ.$q$,$q$أعطال متكررة في مدخل لا يمكن إغلاقه، وخطر انحباس أو اصطدام، وتعطّل مسار الإخلاء.$q$,array[$q$كتالوج المحرك وفئة الاستخدام$q$,$q$شهادة المطابقة لمعايير الأبواب الآلية$q$,$q$مخطط التركيب والحساسات$q$]::text[],'{}'::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-05$q$,$q$LS-62$q$,array[$q$LS-62$q$]::text[],$q$حماية الجدران والأرضيات والأسقف$q$,$q$card$q$,50,$q$حماية الجدران والزوايا$q$,$q$Acrovyn Wall Protection (CS Group)$q$,$q$eq$q$,$q$Acrovyn من CS Group، ويُقبل Gerflor$q$,array[$q$HD$q$,$q$DIS$q$,$q$FIRE$q$,$q$HYG$q$]::text[],$q$[["المادة", "زوايا ألمنيوم أو PVC رقيق، أو الاكتفاء بالدهان", "ألواح وزوايا Acrovyn بسماكة 1.02 – 1.9 مم"], ["ارتفاع حماية الزوايا", "قطع قصيرة", "1.5 م"], ["السلوك عند الحريق", "غير مصنّف", "Class A وفق UL 723 / ASTM E84"], ["التنظيف", "يتشقق أو يصفرّ مع المطهرات", "يتحمّل منظّفات المستشفيات المعتمدة"], ["التركيب", "لاصق أو سيليكون", "نظام تثبيت المصنّع"]]$q$::jsonb,$q$الجدار المكسور أو المقشّر ليس مشكلة شكل فقط؛ هو سطح لا يمكن تطهيره ويتجمع فيه الغبار والبكتيريا، وإصلاحه المتكرر يعني إغلاق الممرات وتكلفة تشغيل دائمة.$q$,$q$تكسّر الزوايا والجبس خلال السنة الأولى، ودهان متكرر، وملاحظات مكافحة العدوى.$q$,array[$q$Data Sheet بالسماكات وتصنيف الحريق$q$,$q$عينة اللون$q$,$q$تفاصيل التثبيت$q$]::text[],array[3]::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-06$q$,$q$LS-58$q$,array[$q$LS-58$q$]::text[],$q$حماية الجدران والأرضيات والأسقف$q$,$q$card$q$,60,$q$الأرضيات الفينيل المتجانسة$q$,$q$Gerflor Mipolam (Infinity) 2 mm Homogeneous$q$,$q$only$q$,$q$Gerflor Mipolam متجانس 2 مم$q$,array[$q$HT$q$,$q$HYG$q$,$q$DIS$q$,$q$HD$q$]::text[],$q$[["نوع المادة", "فينيل غير متجانس أو SPC/LVT بتعشيق، بطبقة سطحية رقيقة", "فينيل متجانس 2 مم: اللون والمادة في كامل السماكة"], ["مقاومة الاحتكاك", "غير موضّحة", "أعلى فئة تآكل (Wear group T)"], ["الفواصل", "فواصل مفتوحة بين القطع", "لحام حراري للفواصل + رفع الأرضية على الجدار (Coving)"], ["الصيانة", "يحتاج تشميعاً دورياً", "معالجة Evercare: بلا تشميع طوال العمر"], ["النظافة", "—", "مثبّط للبكتيريا والفطريات، ومقاوم لبقع الدم واليود"], ["مقاومة الانزلاق", "غير موضّحة", "PTV أعلى من 36"]]$q$::jsonb,$q$الأرضية في المستشفى تُغسل يومياً بالمطهرات وتمر عليها العجلات باستمرار. الفاصل المفتوح يجمع السوائل والبكتيريا، والطبقة السطحية الرقيقة تتآكل فيظهر ما تحتها.$q$,$q$انفصال القطع تحت العجلات، وبقع دائمة، وتجمع الأوساخ في الفواصل والزوايا، واستبدال كامل للأرضية.$q$,array[$q$Data Sheet الأصلي للمنتج$q$,$q$عينة واللون المعتمد$q$,$q$خطاب الوكيل وتأهيل فريق التركيب واللحام$q$]::text[],array[4]::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-07$q$,$q$LS-59$q$,array[$q$LS-59$q$]::text[],$q$حماية الجدران والأرضيات والأسقف$q$,$q$card$q$,70,$q$بلاط البورسلين$q$,$q$EXA Porcelain$q$,$q$only$q$,$q$EXA حسب ما في جدول الكميات$q$,array[$q$HT$q$,$q$UNI$q$]::text[],$q$[["الفئة", "سيراميك أو بورسلين مطلي يظهر لونه الداخلي عند الكسر", "البورسلين المحدد في الجدول — امتصاص ماء ≤ 0.5% (فئة BIa)"], ["الدفعة واللون", "دفعات مختلفة وألوان متفاوتة", "دفعة واحدة موثّقة"], ["الاستبدال لاحقاً", "صعب إيجاد بلاطة مطابقة", "منتج متوفر يسهل الاستبدال منه في الصيانة"]]$q$::jsonb,$q$الاعتماد يضمن ثبات اللون والمقاس وتوفّر البلاط للصيانة مستقبلاً، فلا تتحول كل بلاطة مكسورة إلى رقعة مختلفة.$q$,$q$تفاوت الألوان، وصعوبة الاستبدال، وتشقق الحواف في مناطق العربات.$q$,array[$q$Data Sheet وعينة$q$,$q$رقم الدفعة$q$]::text[],'{}'::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-08$q$,$q$LS-60$q$,array[$q$LS-60$q$]::text[],$q$حماية الجدران والأرضيات والأسقف$q$,$q$card$q$,80,$q$الأسقف المستعارة$q$,$q$USG or MADA Ceiling Systems$q$,$q$only$q$,$q$USG أو MADA (البلاط والشبكة من المنظومة نفسها)$q$,array[$q$HYG$q$,$q$FIRE$q$]::text[],$q$[["البلاط", "ألياف معدنية منخفضة الكثافة", "بلاط مقاوم للرطوبة والترهّل وقابل للمسح"], ["الشبكة", "شبكة رقيقة غير متوافقة مع البلاط", "شبكة من نفس المنظومة"], ["الحريق", "غير موضّح", "تصنيف حريق موثّق"]]$q$::jsonb,$q$الأسقف في المنشأة الصحية تُفتح كثيراً لصيانة التكييف والكهرباء، ويجب ألا تتبقع أو تترهل مع الرطوبة، وأن تبقى قابلة للتنظيف.$q$,$q$بلاط مترهل ومتبقع خلال سنة، وتساقط عند الصيانة.$q$,array[$q$Data Sheet البلاط والشبكة$q$,$q$عينة$q$]::text[],'{}'::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-09$q$,$q$LS-53$q$,array[$q$LS-53$q$]::text[],$q$حماية الجدران والأرضيات والأسقف$q$,$q$card$q$,90,$q$ممسحة المدخل$q$,$q$emco MARSCHALL Premium Large + Care insert$q$,$q$eq$q$,$q$emco MARSCHALL Premium Large مع إدخال Care و517 PSL Care B$q$,array[$q$HT$q$,$q$HD$q$]::text[],$q$[["النوع", "سجادة سطحية أو مطاطية فوق الأرضية", "ممسحة مدمجة في حفرة بالأرضية بإطار وبروفيلات ألمنيوم"], ["الحركة", "تتحرك وتتجعد مع العجلات", "مستوية مع الأرضية ومناسبة للكراسي المتحركة والعربات"], ["الوظيفة", "شكلية", "تحتجز الأتربة والرطوبة عند الباب"]]$q$::jsonb,$q$الأتربة الداخلة من المدخل هي أكبر سبب لتآكل الأرضيات داخل المنشأة، والسجادة السطحية خطر تعثّر.$q$,$q$تعثّر المرضى، وتآكل أسرع للأرضيات، وتنظيف أكثر.$q$,array[$q$Data Sheet ومخطط الحفرة والمقاسات$q$]::text[],array[5]::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-10$q$,$q$LS-53$q$,array[$q$LS-53$q$]::text[],$q$حماية الجدران والأرضيات والأسقف$q$,$q$card$q$,100,$q$الدرابزين ومقابض الجدران$q$,$q$Stainless Steel 304 Handrails$q$,$q$eq$q$,$q$ستانلس ستيل 304$q$,array[$q$DIS$q$,$q$HD$q$]::text[],$q$[["المادة", "حديد مدهون أو ستانلس 201", "ستانلس ستيل 304"], ["مع المطهرات", "يصدأ ويتبقّع مع الكلور", "مقاوم للتآكل"]]$q$::jsonb,$q$الدرابزين يلمسه كل زائر ويُمسح بالمطهرات يومياً. ستانلس 201 يشبه 304 في المظهر لكنه أقل مقاومة للتآكل.$q$,$q$صدأ وبقع خلال أشهر.$q$,array[$q$شهادة المادة (Mill Certificate) تذكر الدرجة 304$q$]::text[],'{}'::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-11$q$,$q$LS-63$q$,array[$q$LS-63$q$]::text[],$q$دورات المياه$q$,$q$card$q$,110,$q$القواطع وأبواب الحمامات$q$,$q$Compact HPL 19 mm (Bobrick or Fundermax)$q$,$q$list$q$,$q$Bobrick أو Fundermax$q$,array[$q$HYG$q$,$q$DIS$q$,$q$HD$q$]::text[],$q$[["المادة", "MDF أو خشب حبيبي مغطى بميلامين، أو كومباكت 12 مم", "Compact HPL مصمت بسماكة 19 مم (EN 438‑4)"], ["مع الماء", "ينتفخ ويتفكك من الأطراف", "لا يتأثر بالماء والرطوبة"], ["الإكسسوارات", "مفصلات وأرجل خفيفة", "مفصلات وأرجل ستانلس ستيل من النظام نفسه"]]$q$::jsonb,$q$القاطع يُغسل يومياً ويتعرض للماء المباشر. المواد الخشبية تنتفخ والطبقة السطحية تنفصل.$q$,$q$انتفاخ الأطراف وتفكك المفصلات خلال أشهر، واستبدال كامل للقواطع.$q$,array[$q$Data Sheet وشهادة EN 438$q$,$q$مخطط الورشة$q$]::text[],'{}'::int[]) on conflict (key) do nothing;
