insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-16$q$,$q$LS-69$q$,array[$q$LS-69$q$]::text[],$q$المصاعد$q$,$q$card$q$,160,$q$المصاعد$q$,$q$Schindler 5000 (MRL)$q$,$q$only$q$,$q$Schindler 5000$q$,array[$q$UNI$q$,$q$HT$q$,$q$247$q$]::text[],$q$[["المنتج", "مصعد مجمّع من مكونات متعددة المصادر", "Schindler 5000 بدون غرفة ماكينات (MRL)"], ["الصيانة", "مورّد غير مرتبط بالمصنع", "وكيل معتمد وقطع غيار أصلية وعقد صيانة"], ["التوحيد", "نظام مختلف عن باقي المنشآت", "توحيد الصيانة وقطع الغيار مع منشآت التجمع"]]$q$::jsonb,$q$تعدد أنواع المصاعد يعني تعدد عقود الصيانة وقطع الغيار وتأخر الإصلاح.$q$,$q$توقف طويل بانتظار قطع غير متوفرة.$q$,array[$q$العرض الفني من الوكيل$q$,$q$شهادات المطابقة والتسليم$q$]::text[],array[8]::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-17$q$,$q$LS-85$q$,array[$q$LS-85$q$]::text[],$q$الأنظمة الكهروميكانيكية والتقنية$q$,$q$card$q$,170,$q$الشاشات الرقمية وشاشات العرض$q$,$q$Samsung QMC Series + Navori — AAHC Digital Signage Standard$q$,$q$eq$q$,$q$Samsung QMC (القياسي)، وQHC للمناطق عالية الإضاءة، وQBC للمناطق الإدارية غير الحرجة — مربوطة بمنصة Navori$q$,array[$q$247$q$,$q$UNI$q$,$q$HD$q$]::text[],$q$[["نوع الشاشة", "تلفزيون منزلي (Consumer TV)", "شاشة عرض تجارية مصممة للتشغيل المتواصل؛ ولا يُركَّب التلفزيون المنزلي في المناطق العامة أو الحرجة"], ["الدقة والسطوع", "غير موضّحة", "4K UHD كحد أدنى، وسطوع 500 nit في سلسلة QMC"], ["الضمان", "ضمان منزلي لا يغطي الاستخدام التجاري", "ضمان تجاري 3 سنوات يغطي التشغيل 24/7"], ["إدارة المحتوى", "تشغيل محلي من USB", "منصة Navori إلزامية في المناطق العامة (مشغّل مدمج أو خارجي)؛ للتوعية الصحية وأرقام الدور والتنبيهات الطارئة"], ["الكهرباء", "مقبس واحد وتمديدة ظاهرة", "مقبسان خلف الشاشة (للشاشة وللمشغّل)، ويُفضَّل ربط أحدهما بالطوارئ/UPS"], ["الشبكة", "اتصال لاسلكي", "نقطة شبكة سلكية RJ45 لكل شاشة؛ واللاسلكي بموافقة تقنية المعلومات فقط"], ["الكابلات", "أسلاك متدلية ظاهرة", "كل الكابلات مخفية خلف الشاشة أو في مجارٍ معتمدة"], ["الارتفاع والمقاس", "حسب الاجتهاد", "حسب جداول المعيار: الانتظار الصغيرة 43–55 بوصة بمنتصف 1.5–1.7 م، والردهة الرئيسية 65–75 بوصة بمنتصف 1.7–2.0 م"]]$q$::jsonb,$q$الشاشة في صالات الانتظار قناة التجمع للتوعية الصحية وإدارة الدور والتنبيهات الطارئة، وتعمل طوال ساعات التشغيل. والربط بمنصة Navori يسمح ببث المحتوى من مكان واحد لكل المنشآت.$q$,$q$تلفزيون يتعطل ويسقط ضمانه، وشاشة لا يمكن إدارتها مركزياً، وأسلاك ظاهرة لا تليق بالمنشأة.$q$,array[$q$Data Sheet الموديل$q$,$q$جدول مواقع الشاشات بالمقاسات والارتفاعات$q$,$q$تأكيد التوافق مع Navori ونقاط الكهرباء والشبكة$q$]::text[],array[17,9]::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-18$q$,$q$LS-86$q$,array[$q$LS-86$q$]::text[],$q$الأنظمة الكهروميكانيكية والتقنية$q$,$q$card$q$,180,$q$نظام إنذار الحريق العنواني$q$,$q$Gent by Honeywell — Addressable, Online Monitoring$q$,$q$list$q$,$q$Gent من Honeywell، مربوط بالشبكة المركزية للمراقبة$q$,array[$q$FIRE$q$,$q$UNI$q$,$q$247$q$]::text[],$q$[["نوع النظام", "نظام تقليدي (Conventional) يحدد المنطقة فقط", "نظام عنواني (Addressable) يحدد الكاشف بعينه"], ["المراقبة", "لوحة محلية لا يراها إلا من في المبنى", "مربوط بالشبكة المركزية للمراقبة والتحكم عن بُعد (Online web monitoring)"], ["الربط مع الأنظمة", "محدود أو غير موجود", "إيقاف التكييف وإغلاق مخامد الحريق، والإخلاء الصوتي، وفتح الباب الأوتوماتيكي وأذرع الطوارئ، واستدعاء المصعد"], ["الكابلات", "كابلات عادية", "كابلات LSZH قليلة الدخان وخالية من الهالوجين"], ["الاعتماد", "—", "معتمد من الدفاع المدني"]]$q$::jsonb,$q$المريض في المنشأة الصحية قد لا يستطيع الإخلاء وحده، فكل دقيقة مهمة. والربط بالمراقبة المركزية يوصل الإنذار إلى غرفة التحكم في التجمع حتى خارج أوقات الدوام.$q$,$q$إنذارات لا يُعرف مصدرها بدقة، ونظام معزول لا يراه أحد ليلاً، ورفض في فحص الدفاع المدني.$q$,array[$q$اعتماد الدفاع المدني للمخططات$q$,$q$Data Sheet اللوحة والكواشف$q$,$q$مصفوفة الربط مع الأنظمة (Cause & Effect)$q$]::text[],'{}'::int[]) on conflict (key) do nothing;
insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-19$q$,$q$LS-87$q$,array[$q$LS-87$q$]::text[],$q$الأنظمة الكهروميكانيكية والتقنية$q$,$q$card$q$,190,$q$كاميرات المراقبة$q$,$q$Hikvision Ultra Series Smart IP$q$,$q$list$q$,$q$Hikvision Ultra Series Smart IP، مع مفاتيح PoE من Huawei وكابلات Cat6A من Belden$q$,array[$q$UNI$q$,$q$247$q$,$q$HD$q$]::text[],$q$[["دقة الكاميرا", "2 – 4 ميجابكسل غالباً", "8 ميجابكسل ليلية/نهارية بالأشعة تحت الحمراء"], ["الكاميرات الخارجية", "غير مصنفة", "Bullet أو PTZ بحماية IP66"], ["التسجيل", "جهاز تسجيل تماثلي أو أقراص عادية", "NVR شبكي ببحث ذكي (AI) وأقراص مخصصة للمراقبة بسعة تكفي مدة الحفظ"], ["الشبكة", "مفاتيح وكابلات عامة", "مفاتيح PoE من Huawei وكابلات Cat6A من Belden"], ["الاستلام", "تشغيل فقط", "اختبار وضوح الصورة ليلاً ونهاراً وزوايا التغطية ومدة التخزين الفعلية"]]$q$::jsonb,$q$الكاميرا تُراجَع عند حادث أو بلاغ، وقيمتها في وضوح الصورة ليلاً ومدة الحفظ. وتوحيد النوع يسمح بربطها بمنظومة المراقبة لدى التجمع.$q$,$q$صورة لا تُظهر الوجوه ليلاً، وتسجيل يُمسح قبل المدة المطلوبة، ونظام لا يمكن ربطه.$q$,array[$q$مخطط توزيع الكاميرات وزوايا التغطية$q$,$q$Data Sheet الكاميرا والـ NVR$q$,$q$حساب سعة التخزين$q$]::text[],'{}'::int[]) on conflict (key) do nothing;
