insert into public.guide_cards(key,code_label,ls_codes,section,kind,sort,title,en,rule,approved,badges,rows,why,risk,submit,refs) values ($q$G-29$q$,$q$LS-93$q$,array[$q$LS-93$q$]::text[],$q$الأثاث غير الطبي والمكتبي$q$,$q$card$q$,290,$q$الأثاث المكتبي ومقاعد الانتظار$q$,$q$Herman Miller · Global · OFS · Steelcase$q$,$q$list$q$,$q$Herman Miller · Global · OFS · Steelcase$q$,array[$q$HD$q$,$q$HT$q$,$q$247$q$,$q$DIS$q$,$q$WAR$q$]::text[],$q$[["الاختبارات", "لا توجد تقارير اختبار، أو ادعاءات عامة", "اختبارات ANSI/BIFMA: X5.1 للكراسي، X5.4 لمقاعد الانتظار، X5.5 للمكاتب والطاولات"], ["ساعات الاستخدام", "مصمم لاستخدام مكتبي فردي لوردية واحدة", "خيارات للاستخدام المتواصل 24/7 متعدد الورديات (كاونترات الاستقبال، التمريض، غرف التحكم)"], ["الضمان", "سنة إلى سنتين غالباً", "Herman Miller: 12 سنة لكثير من المنتجات على أساس 3 ورديات · Global: 12 سنة لكل المكونات في فئة Heavy Duty · OFS: 12 سنة للمنتجات القياسية · Steelcase: ضمان محدود مدى الحياة لعدد من المكونات"], ["القماش — المسحات المزدوجة", "15,000 – 30,000 أو غير موضّح", "لا يقل عن 75,000 مسحة مزدوجة للرعاية الصحية، وأكثر من 100,000 لفئة Heavy Duty"], ["قابلية التنظيف", "قماش يمتص السوائل والبقع", "تنجيد غير منفذ للسوائل يتحمّل منظّفات المستشفيات، وفراغ تنظيف بين المقعد والظهر"], ["الحريق", "غير مختبر", "Class A لانتشار اللهب ودخان ≤ 450 (ASTM E84)، وأقمشة مختبرة حسب نوعها"], ["التحمّل", "غير محدد", "136 كجم لمقاعد الانتظار والكراسي المكتبية، و340 كجم للمقاعد المخصصة لذوي الوزن العالي"], ["الهيكل والأسطح", "خشب حبيبي تنتفخ حوافه، ومسامير ظاهرة", "هياكل معدنية وأسطح عالية الضغط وحواف محكمة"]]$q$::jsonb,$q$لأنها تختبر منتجاتها وفق معايير BIFMA وتنشر نتائجها، وتقدّم ضمانات مكتوبة طويلة تغطي الاستخدام المتعدد الورديات، وتوفّر أقمشة مصممة للتنظيف بالمطهرات. وهذا ما يجعل الكرسي يبقى صالحاً عشر سنوات بدل سنة أو سنتين.$q$,$q$تمزق القماش وتبقّعه، وانكسار القواعد والمساند، وانتفاخ الأسطح الخشبية، وفي المنشأة الصحية: قماش لا يمكن تطهيره ولا بد من استبداله.$q$,array[$q$تقارير اختبار BIFMA من مختبر معتمد$q$,$q$بيانات القماش (المسحات المزدوجة وقابلية التطهير والحريق)$q$,$q$خطاب الضمان من المصنّع$q$,$q$عينات القماش والتشطيب$q$]::text[],array[14]::int[]) on conflict (key) do nothing;
  insert into public.settings(key, value, updated_at) values ('guide_meta', $q${"sections": [{"name": "الأبواب والأقفال والإكسسوارات المعدنية", "intro": "أكثر عناصر المبنى حركةً؛ الباب في ممر مستشفى يُفتح مئات المرات يومياً ويصطدم به السرير والعربة والكرسي المتحرك."}, {"name": "حماية الجدران والأرضيات والأسقف", "intro": "الأسطح التي يلمسها السرير والعربة والمطهّر كل يوم. معيارها ليس الشكل يوم التسليم، بل الحال بعد خمس سنوات من التنظيف اليومي."}, {"name": "دورات المياه", "intro": "أكثر المناطق رطوبةً وتنظيفاً واستخداماً. كل مادة تمتص الماء أو تصدأ ستظهر مشكلتها في السنة الأولى."}, {"name": "المصاعد", "intro": "المصعد في المنشأة الصحية ينقل المرضى والأسرّة والطوارئ، وتوقّفه يوقف الخدمة."}, {"name": "الأنظمة الكهروميكانيكية والتقنية", "intro": "هذه الأنظمة تعمل خلف الجدران، لكنها ترتبط بشبكات التجمع ولوحات التحكم وعقود الصيانة القائمة. لذلك يكون الاعتماد هنا أساسه التوافق والتوحيد قبل أي شيء."}, {"name": "الأثاث غير الطبي والمكتبي", "intro": "كراسي الانتظار وكاونترات الاستقبال ومكاتب التمريض والإدارة. أكثر بند يتشابه فيه الشكل ويختلف فيه العمر الفعلي، وأكثر بند يُعرض فيه البديل المحلي بسعر أقل."}], "sources": [["Allegion — What are ANSI/BHMA hardware grades?", "https://kc.allegion.com/kb/article/what-are-ansi-bhma-hardware-grades"], ["SALTO — XS4 Original datasheet", "https://cms.saltosystems.com/sites/default/files/products/download/datasheet-xs4_original_sx6xxk-eng-10-20.pdf"], ["Construction Specialties — Acrovyn healthcare wall covering", "https://www.c-sgroup.com/category/wall-protection/product-selector/healthcare-wall-covering"], ["RIBA Journal — Gerflor Mipolam with Evercare treatment", "https://www.ribaj.com/spec/mipolam-with-evercare-treatment/"], ["ArchiExpo — emco MARSCHALL Premium entrance mat", "https://www.archiexpo.com/prod/emco-bautechnik-gmbh/product-54726-2566842.html"], ["KaTom — Koala Kare KB310‑SSRE", "https://www.katom.com/107-KB310SSRE.html"], ["Gulf Construction — Geberit extends parts guarantee to 50 years", "https://gulfconstructiononline.com/Article/385983/Geberit_extends_parts_guarantee_to_50_years"], ["Buildings — Schindler 5000 MRL elevator", "https://www.buildings.com/products/elevators-escalators/product/55287081/schindler-elevator-corp-this-machine-room-less-mrl-elevator-features-taller-cars-larger-entrances-and-higher-load-capacities"], ["Crown TV — Samsung QMC series", "https://crowntv-us.com/blog/samsung-qmc-series-2025/"], ["Herman Miller — Warranty", "https://www.hermanmiller.com/warranty/"], ["Global Furniture Group — Warranty", "https://www.eandi.org/wp-content/uploads/Global_warranty_8.20.pdf"], ["OFS — Warranty", "https://imagineaplace.ofs.com/page/warranty"], ["Steelcase — Warranty FAQ", "https://steelcase.com/resources/documents/faq-warranty"], ["U.S. Defense Health Agency — DHA 12 52 00 Healthcare Seating", "https://www.wbdg.org/FFC/DHA/DHA%2012%2052%2000.pdf"], ["Brentano — Abrasion (ACT guidelines)", "https://brentanofabrics.com/faqs/abrasion/"], ["SOLT — Patient‑Nurse Wireless Calling System", "https://www.solteurope.com/pages/patient-nurse-wireless-calling-system"], ["تجمع الأحساء الصحي — معيار تركيب الشاشات الرقمية والتلفزيونات AAHC-FM-STD-DIGITAL-SIGNAGE-001 (الإصدار 0 — مسودة)، مالكه إدارة المرافق", ""]], "standards": ["AAHC-FM-STD-DIGITAL-SIGNAGE-001 — معيار التجمع للشاشات الرقمية", "ANSI/SDI A250.8 — الأبواب والحلوق المعدنية", "ANSI/BHMA A156.1 / .2 / .3 / .4 / .13 — إكسسوارات الأبواب", "EN 16005 — سلامة الأبواب الآلية", "UL 723 / ASTM E84 — انتشار اللهب والدخان", "EN 438‑4 — ألواح Compact HPL", "ISO 13006 / EN 14411 — بلاط السيراميك والبورسلين", "ADA 2010 Standards §609 — مقابض الإسناد", "ANSI/BIFMA X5.1 / X5.4 / X5.5 — الأثاث المكتبي وكراسي الانتظار والطاولات", "ASTM D4157 (Wyzenbeek) — مقاومة القماش للاحتكاك"]}$q$::jsonb, now()) on conflict (key) do nothing;
