-- 0070: بطاقات «دليل المواصفات المعتمدة» (يُصدَّر PDF من جدول كميات المشروع باسمه) + معيار الشاشات الرقمية للتجمع
create table if not exists public.guide_cards (
  key text primary key, code_label text not null default '', ls_codes text[] not null default '{}', section text not null default '',
  kind text not null default 'card', sort int not null default 0, title text not null, en text not null default '', rule text not null default 'list',
  approved text not null default '', badges text[] not null default '{}', rows jsonb not null default '[]', why text not null default '', risk text not null default '',
  submit text[] not null default '{}', refs int[] not null default '{}', active boolean not null default true, updated_at timestamptz not null default now());
alter table public.guide_cards enable row level security;
grant select, insert, update, delete on public.guide_cards to authenticated;
drop policy if exists p_read on public.guide_cards; create policy p_read on public.guide_cards for select using (public.can_read());
drop policy if exists p_admin on public.guide_cards; create policy p_admin on public.guide_cards for all using (public.is_admin()) with check (public.is_admin());

do $$ begin
  if exists (select 1 from public.seed_marks where key = 'guide_cards_v1') then return; end if;
end $$;

-- بند المقطوعية LS-85 في القائمة (للجداول الجديدة فقط): إلحاق اشتراطات معيار الشاشات مرة واحدة
update public.ls_items set descr = descr || ' ' || $q$ويلتزم المقاول بمعيار تجمع الأحساء الصحي للشاشات الرقمية AAHC-FM-STD-DIGITAL-SIGNAGE-001: شاشات عرض تجارية مصممة للتشغيل المتواصل (Samsung QMC أو ما يعادلها المعتمد، وQHC للمناطق عالية الإضاءة) بدقة 4K UHD كحد أدنى، ولا يُقبل التلفزيون المنزلي في المناطق العامة؛ وربط شاشات المناطق العامة بمنصة Navori بمشغّل مدمج أو خارجي؛ ومقبسان كهربائيان خلف كل شاشة (أحدهما على الطوارئ/UPS حيث أمكن) ونقطة شبكة سلكية RJ45؛ وإخفاء جميع الكابلات خلف الشاشة أو في مجارٍ معتمدة؛ والمقاسات وارتفاعات التركيب حسب جداول المعيار.$q$, updated_at = now()
  where code = 'LS-85' and position('AAHC-FM-STD-DIGITAL-SIGNAGE-001' in descr) = 0;

-- اشتراط تسليم الشاشات
  $q$يسلّم المقاول جدول مواقع الشاشات (الموقع، الموديل، المقاس، ارتفاع منتصف الشاشة عن الأرضية المنتهية) مطابقاً لمعيار تجمع الأحساء الصحي AAHC-FM-STD-DIGITAL-SIGNAGE-001، مع إثبات ربط كل شاشة في المناطق العامة بمنصة Navori، وتوفير مقبسين ونقطة شبكة سلكية خلف كل شاشة، وإخفاء جميع الكابلات.$q$,
  $q$جدول Excel + صورة لكل شاشة بعد التركيب + تأكيد تقنية المعلومات للربط مع Navori$q$,$q$قبل الاستلام الابتدائي$q$,105) on conflict (code) do nothing;
